--SET DEFINE OFF

--UNCOMMENT SET SQLBLANKLINES ON TO RUN THIS SCRIPT IN SQLPLUS

--SET SQLBLANKLINES ON

DROP VIEW PS_SEC_DEPT_PR_VW
/
CREATE VIEW PS_SEC_DEPT_PR_VW (SCRTY_KEY1, DEPTID, DESCR) AS SELECT
 SETID , DEPTID , DESCR FROM PS_DEPT_TBL D WHERE D.EFFDT=(SELECT
 MAX(EFFDT) FROM PS_DEPT_TBL B WHERE B.SETID=D.SETID AND
 B.DEPTID=D.DEPTID AND B.EFFDT<=TO_DATE(TO_CHAR(SYSDATE,'YYYY-MM-DD')
,'YYYY-MM-DD'))
/